//! Exact source activation and multiple real cast/entry transactions.
use ironsmith::{CardDefinition,GameProgress,GameState,ObjectId,PlayerId,Zone};
use ironsmith::decision::{LegalAction,SelectFirstDecisionMaker,compute_legal_actions};
use ironsmith::game_loop::{PriorityLoopState,PriorityResponse,apply_priority_response_with_dm,apply_decision_context_with_dm,resolve_stack_entry_with};
use ironsmith::object::CounterType;
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
fn action(game:&mut GameState,action:LegalAction){let mut queue=ironsmith::triggers::TriggerQueue::new();let mut state=PriorityLoopState::new(2);let mut dm=SelectFirstDecisionMaker;let mut progress=apply_priority_response_with_dm(game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){return}let GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("{progress:?}")};progress=apply_decision_context_with_dm(game,&mut queue,&mut state,&ctx,&mut dm).unwrap();}panic!("unfinished announcement")}
fn mainphase(game:&mut GameState){game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;}
fn cast(game:&mut GameState,definition:&CardDefinition)->ObjectId{mainphase(game);let source=game.create_object_from_definition(definition,A,Zone::Hand);let stable=game.object(source).unwrap().stable_id;let choice=compute_legal_actions(game,A).unwrap().into_iter().find(|a|matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==source)).unwrap();action(game,choice);resolve_stack_entry_with(game,&mut SelectFirstDecisionMaker).unwrap();game.find_object_by_stable_id(stable).unwrap()}
fn attack(game:&mut GameState){let body=ironsmith_compiler_runtime::compile_to_runtime_definition("Attack witness","Type: Creature\nPower/Toughness: 1/1",false).unwrap();let id=game.create_object_from_definition(&body,A,Zone::Battlefield);game.remove_summoning_sickness(id);game.turn.active_player=A;game.turn.phase=ironsmith::game_state::Phase::Combat;game.turn.step=Some(ironsmith::game_state::Step::DeclareAttackers);game.mark_combat_phase_started();let mut combat=ironsmith::combat_state::CombatState::default();ironsmith::game_loop::apply_attacker_declarations(game,&mut combat,&mut ironsmith::triggers::TriggerQueue::new(),&[ironsmith::decision::AttackerDeclaration{creature:id,target:ironsmith::combat_state::AttackTarget::Player(B)}]).unwrap();}
#[test]
fn fanatical_vanguard_grants_each_creature_cast_only_for_the_current_turn(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/msem-malign.json")).unwrap();let row=fixture["mechanics"].as_array().unwrap().iter().find(|r|r["id"]=="msem-970").unwrap();let card=&row["representative_cards"][0];
 let(result,loss)=ironsmith_compiler::parse_loss::capture(||ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact(card["name"].as_str().unwrap(),card["executable_text"].as_str().unwrap(),false)));assert!(!loss.is_lossy(),"{}",loss.reasons_text());let(artifact,direct)=result.unwrap();let restored=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();
 for definition in [direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&restored).unwrap()]{for attacked in [false,true]{
  let mut game=GameState::new(vec!["A".into(),"B".into()],20);if attacked{attack(&mut game)}mainphase(&mut game);let provider=game.create_object_from_definition(&definition,A,Zone::Graveyard);let stable=game.object(provider).unwrap().stable_id;game.player_mut(A).unwrap().mana_pool.add(ironsmith::ManaSymbol::Red,1);
  let activate=compute_legal_actions(&game,A).unwrap().into_iter().find(|a|matches!(a,LegalAction::ActivateAbility{source,..}if *source==provider)).unwrap();action(&mut game,activate);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Exile);assert_eq!(game.player(A).unwrap().mana_pool.total(),0);resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();
  let creature=ironsmith_compiler_runtime::compile_to_runtime_definition("Recipient creature","Mana cost: {0}\nType: Creature\nPower/Toughness: 1/1",false).unwrap();let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Noncreature recipient","Mana cost: {0}\nType: Artifact",false).unwrap();let unrelated=cast(&mut game,&artifact);assert_eq!(game.counter_count(unrelated,CounterType::PlusOnePlusOne),0);
  for _ in 0..2{let entered=cast(&mut game,&creature);assert_eq!(game.counter_count(entered,CounterType::PlusOnePlusOne),u32::from(attacked));}
  game.next_turn();attack(&mut game);let later=cast(&mut game,&creature);assert_eq!(game.counter_count(later,CounterType::PlusOnePlusOne),0);
 }}
}
